"""Build the public YELLOW site from approved public product metadata."""
from pathlib import Path
import json,html,shutil
ROOT=Path(__file__).resolve().parent
OUT=(ROOT.parent/'public') if (ROOT.parent/'public').exists() else ROOT.parent/'.local/runtime-deploy/runtime-worker/public'
products=json.loads((ROOT/'data/products.json').read_text())
e=html.escape
def t(ru,en):return f'<span data-lang="ru">{ru}</span><span data-lang="en" hidden>{en}</span>'
def link(url,ru,en,cls=''):return f'<a class="{cls}" href="{url}">{t(ru,en)}</a>'
nav=[('/catalog/','Каталог','Catalogue'),('/applications/','Применение','Applications'),('/documents/','Документация','Documents'),('/runtime/','Калькулятор','Calculator'),('/partners/','Партнёрам','Partners')]
def write_changed(path, value):
 path.parent.mkdir(parents=True,exist_ok=True)
 if not path.exists() or path.read_text()!=value:path.write_text(value)
def copy_changed(source, target):
 target.parent.mkdir(parents=True,exist_ok=True)
 if not target.exists() or source.read_bytes()!=target.read_bytes():shutil.copy2(source,target)
def page(path,title,body):
 active='/'+path.split('/')[0]+'/' if path else '/'
 links=''.join(link(u,r,n,'current' if u==active else '') for u,r,n in nav)
 markup=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{e(title)} — YELLOW</title><meta name="description" content="Аккумуляторные батареи YELLOW. Каталог AGM, документация и подбор автономии."><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script></head><body><a class="skip" href="#main">{t('К содержанию','Skip to content')}</a><div class="test-strip">{t('YELLOW / Предварительная версия сайта','YELLOW / Website preview')}</div><header class="site-header"><a class="logo" href="/" aria-label="YELLOW"><img src="/assets/yellow.svg" alt="YELLOW" width="180" height="32"></a><button class="menu-button" aria-expanded="false" aria-controls="site-nav">{t('Меню','Menu')} ☰</button><nav id="site-nav" aria-label="Основная навигация">{links}</nav><div class="language" role="group" aria-label="Language"><button data-language="en" aria-pressed="false">EN</button><button data-language="ru" aria-pressed="true">RU</button></div>{link('/admin/','Кабинет ↗','Account ↗','account-link')}</header><main id="main">{body}</main><footer class="site-footer"><div class="footer-top"><a href="/" class="logo"><img src="/assets/yellow.svg" alt="YELLOW" width="180" height="32"></a><p>{t('Энергия для резервного питания.','Energy for standby power.')}</p>{link('/contacts/','Контакты ↗','Contact ↗')}</div><div class="footer-bottom"><span>Harbin Haoneng New Energy Technology Co., Ltd.</span><div>{link('/about/','О YELLOW','About YELLOW')}{link('/documents/','Документация','Documents')}{link('/admin/','Вход для партнёров','Partner sign-in')}</div><span>© 2026 YELLOW</span></div></footer></body></html>'''
 target=OUT/path/'index.html';write_changed(target,markup)
def intro(kicker,ru,en,desc_ru,desc_en):return f'<section class="page-intro wrap"><p class="eyebrow">{kicker}</p><h1>{t(ru,en)}</h1><p class="intro-text">{t(desc_ru,desc_en)}</p></section>'
def series_cards():
 return ''.join(f'<a class="series-card" href="/catalog/?series={s}"><div><span class="eyebrow">AGM / 12 V</span><h3>{s.replace("-"," ")}</h3></div><img src="{next(m["drawing"] for m in products if m["series"]==s)}" alt="{s}" loading="lazy"><div class="series-bottom"><span>{t("Моделей:","Models:")} {len([m for m in products if m["series"]==s])}</span><span aria-hidden="true">↗</span></div></a>' for s in ['HR-M','HRL-M','HR-WM','HRL-WM'])
hero=next(m for m in products if m['id']=='HRL 12-100M')
page('', 'Аккумуляторные батареи',f'''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow">STANDBY POWER / YELLOW</p><h1>{t('Энергия,<br>когда она<br><em>нужна.</em>','Power.<br>When you<br><em>need it.</em>')}</h1><p>{t('Аккумуляторные батареи для систем резервного питания. От выбора модели до расчёта автономии.','Batteries for standby power systems. From choosing a model to calculating runtime.')}</p><div class="button-row">{link('/catalog/','Выбрать батарею ↗','Explore batteries ↗','button dark')}{link('/runtime/','Рассчитать автономию →','Calculate runtime →','text-link')}</div></div><div class="hero-visual"><div class="visual-top"><span>ENGINEERED TO BACK UP</span><span>01 / AGM</span></div><div class="drawing-frame"><img src="{hero['drawing']}" alt="Габаритный чертёж HRL 12-100M"></div><div class="visual-bottom"><div><span>YELLOW</span><strong>HRL 12-100M</strong></div><div>12 V <span>/</span> 100 Ah</div></div></div></section><section class="facts wrap"><div><strong>26</strong><span>{t('моделей в каталоге','models in the catalogue')}</span></div><div><strong>12 V</strong><span>{t('номинальное напряжение','nominal voltage')}</span></div><div><strong>AGM</strong><span>{t('технология батарей','battery technology')}</span></div><div><strong>RU / EN</strong><span>{t('инженерный калькулятор','engineering calculator')}</span></div></section><section class="section wrap"><div class="section-head"><div><p class="eyebrow">01 / {t('КАТАЛОГ','CATALOGUE')}</p><h2>{t('Найдите свою серию.','Find your series.')}</h2></div>{link('/catalog/','Все модели ↗','All models ↗','text-link')}</div><div class="series-grid">{series_cards()}</div></section><section class="tool-band"><div class="wrap tool-grid"><div><p class="eyebrow">02 / {t('ИНЖЕНЕРНЫЙ ИНСТРУМЕНТ','ENGINEERING TOOL')}</p><h2>{t('От нагрузки<br>к конфигурации.','From load<br>to configuration.')}</h2><p>{t('Укажите мощность и время автономной работы. Сравните подходящие модели и количество батарей.','Enter your load and required runtime. Compare suitable models and battery quantities.')}</p>{link('/runtime/','Открыть калькулятор ↗','Open calculator ↗','button yellow')}</div><ol class="workflow"><li><span>01</span>{t('Время автономии и нагрузка','Runtime and load')}</li><li><span>02</span>{t('Ступенчатый профиль','Stepped load profile')}</li><li><span>03</span>{t('Время работы выбранной батареи','Runtime of a selected battery')}</li></ol></div></section><section class="section wrap split"><div><p class="eyebrow">03 / {t('ДОКУМЕНТАЦИЯ','DOCUMENTATION')}</p><h2>{t('Характеристики.<br>Без догадок.','Specifications.<br>Clearly documented.')}</h2></div><div><p class="large-copy">{t('Ёмкость, условия разряда, габариты и электрические характеристики — в отдельных листовках для каждой модели.','Capacity, discharge conditions, dimensions and electrical ratings — in a dedicated datasheet for every model.')}</p>{link('/documents/','Скачать документацию ↗','Download documents ↗','text-link')}</div></section>''')
rows=''
for m in sorted(products,key=lambda m:(m['series'],m['capacity'])):
 rows+=f'''<article class="product-card" data-product data-series="{m['series']}" data-capacity="{m['capacity']}" data-name="{e(m['id'])}"><a class="product-image" href="/catalog/{m['slug']}/"><img src="{m['drawing']}" alt="{e(m['id'])}" loading="lazy"></a><div class="product-info"><p class="eyebrow">{m['series']} / AGM</p><h2><a href="/catalog/{m['slug']}/">{m['id']}</a></h2><div class="product-rating"><strong>{m['capacity']:g} <span>{t('А·ч','Ah')}</span></strong><span>12 V</span></div><p class="rating-condition">{m['hours']} {t('ч','h')} · {m['end_voltage']:g} V · {m['temperature']} °C</p><p class="dimensions">{m['overall_dimensions']} {t('мм','mm')}</p><div class="product-actions">{link('/catalog/'+m['slug']+'/','Подробнее ↗','Details ↗')}{link(m['pdf'],'Листовка ↓','Datasheet ↓')}</div></div></article>'''
filters=''.join(f'<button class="filter-tab" data-series-filter="{s}" aria-pressed="false">{s.replace("-"," ")}</button>' for s in ['HR-M','HRL-M','HR-WM','HRL-WM'])
page('catalog','Каталог',intro('PRODUCT RANGE / 01','Батарея под вашу задачу.','A battery for your application.','Выберите серию и ёмкость. Условия измерения указаны для каждой модели.','Choose a series and capacity. Rating conditions are provided for every model.')+f'''<section class="wrap catalog-section"><form id="catalog-filters" class="filter-panel"><div class="filter-tabs" role="group" aria-label="Series"><button class="filter-tab" data-series-filter="" aria-pressed="true">{t('Все серии','All series')}</button>{filters}</div><div class="filter-fields"><label>{t('Поиск модели','Find a model')}<input id="model-search" type="search" placeholder="HRL 12-100M" autocomplete="off"></label><label>{t('Ёмкость от, А·ч','Min. capacity, Ah')}<input id="capacity-min" type="number" min="0" step="any" placeholder="0"></label><label>{t('Ёмкость до, А·ч','Max. capacity, Ah')}<input id="capacity-max" type="number" min="0" step="any" placeholder="250"></label><button class="reset-filters" type="reset">{t('Сбросить','Reset')}</button></div></form><div class="catalog-caption"><p role="status">{t('Найдено моделей:','Models found:')} <strong id="product-count">26</strong></p><p>{t('Габариты: длина × ширина × полная высота','Dimensions: length × width × overall height')}</p></div><div class="product-grid">{rows}</div><div id="no-results" class="empty-state" hidden><h2>{t('Модели не найдены','No models found')}</h2><p>{t('Измените запрос или сбросьте фильтры.','Change your search or reset the filters.')}</p></div><aside class="note">{t('Ёмкости сравнивайте при одинаковых условиях разряда. Для выбора конфигурации под нагрузку используйте калькулятор.','Compare capacities at matching discharge conditions. Use the calculator to size a configuration for your load.')}</aside></section>''')
for m in products:
 specs=[('Номинальное напряжение','Nominal voltage','12 V'),('Номинальная ёмкость','Rated capacity',f'{m["capacity"]:g} Ah'),('Условия измерения ёмкости','Capacity rating conditions',f'{m["hours"]} h / {m["end_voltage"]:g} V / {m["temperature"]} °C'),('Габариты Д × Ш × полная В','L × W × overall H',m['overall_dimensions']+' mm'),('Масса, приблизительно','Approximate weight',m['weight']),('Буферное / циклическое напряжение','Float / cycle voltage',m['charging']),('Максимальный зарядный ток','Maximum charge current',m['max_charge'])]
 table=''.join(f'<div><dt>{t(r,n)}</dt><dd>{e(v)}</dd></div>' for r,n,v in specs)
 page('catalog/'+m['slug'],m['id'],f'''<div class="wrap breadcrumb">{link('/catalog/','Каталог','Catalogue')} <span>/ {m['series']} / {m['id']}</span></div><section class="wrap product-detail"><div class="detail-drawing"><img src="{m['drawing']}" alt="{m['id']}"><p>{t('Габаритный чертёж из листовки модели','Dimensional drawing from the product datasheet')}</p></div><div><p class="eyebrow">{m['series']} / VRLA AGM</p><h1>{m['id']}</h1><p class="detail-lead">{t('Аккумуляторная батарея для резервного питания.','Battery for standby power applications.')}</p><div class="detail-rating"><strong>{m['capacity']:g} <small>{t('А·ч','Ah')}</small></strong><strong>12 <small>V</small></strong></div><p>{m['hours']} {t('ч до','h to')} {m['end_voltage']:g} V {t('при','at')} {m['temperature']} °C</p><div class="button-row">{link(m['pdf'],'Скачать листовку · EN ↓','Download datasheet · EN ↓','button dark')}{link('/runtime/?model='+m['id'].replace(' ','%20'),'Рассчитать автономию ↗','Calculate runtime ↗','button outline')}</div></div></section><section class="section wrap spec-section"><div><p class="eyebrow">TECHNICAL DATA</p><h2>{t('Основные<br>характеристики.','Principal<br>specifications.')}</h2><p class="muted">{t('Подробные условия эксплуатации, допуски, клеммы и разрядные таблицы — в листовке.','See the datasheet for operating conditions, tolerances, terminals and discharge tables.')}</p></div><dl class="spec-table">{table}</dl></section>''')
docrows=''.join(f'<a class="document-row" href="{m["pdf"]}"><span>{m["id"]}</span><span>{m["series"]}</span><span>PDF / EN</span><strong>↓</strong></a>' for m in sorted(products,key=lambda x:(x['series'],x['capacity'])))
page('documents','Документация',intro('DOWNLOAD CENTRE / 02','Всё о батарее.<br>В одном месте.','Everything about your battery.<br>In one place.','Каталог серий и технические листовки YELLOW. Документы доступны на английском языке.','YELLOW series catalogue and technical datasheets. Documents are available in English.')+f'''<section class="wrap"><a class="download-feature" href="/downloads/YELLOW-EN-CATALOGUE.pdf"><div><p class="eyebrow">YELLOW / PRODUCT CATALOGUE</p><h2>{t('Общий каталог','Product catalogue')}</h2><p>{t('4 серии · 26 моделей · основные характеристики','4 series · 26 models · principal specifications')}</p></div><span class="download-arrow">↓</span></a><div class="section-head"><h2>{t('Листовки моделей','Product datasheets')}</h2><span>PDF / EN</span></div><div class="document-list">{docrows}</div></section>''')
applicationcards=[('01','Источники бесперебойного питания','Uninterruptible power supplies','Подбор батарейной линейки по мощности нагрузки и требуемой автономии.','Size battery strings for load power and required runtime.'),('02','Телекоммуникации','Telecommunications','Резервное питание оборудования связи с учётом напряжения системы и условий эксплуатации.','Backup power for communications equipment, considering system voltage and operating conditions.'),('03','Инженерные системы','Building systems','Выбор батарей для резервного питания автоматики и вспомогательного оборудования.','Battery selection for backup power to controls and auxiliary equipment.')]
page('applications','Применение',intro('APPLICATIONS / 03','Резерв для важных систем.','Backup for essential systems.','Конфигурация батарей определяется нагрузкой, временем автономии и требованиями оборудования.','Battery configurations depend on load, runtime and equipment requirements.')+'<section class="wrap editorial-grid">'+''.join(f'<article class="editorial-card"><p class="eyebrow">{num}</p><h2>{t(r,n)}</h2><p>{t(d,ed)}</p>{link("/runtime/","Перейти к расчёту ↗","Go to calculator ↗","text-link")}</article>' for num,r,n,d,ed in applicationcards)+'</section><section class="wrap section"><aside class="note">'+t('Совместимость с зарядным устройством, допустимые токи, защита и условия монтажа проверяются при проектировании системы.','Charger compatibility, current limits, protection and installation conditions must be checked during system design.')+'</aside></section>')
page('partners','Партнёрам',intro('PARTNER PROGRAMME / 04','YELLOW на вашем сайте.','YELLOW on your website.','Каталог, расчёты и техническая информация для работы с вашими клиентами.','Catalogue, calculations and technical information for working with your customers.')+f'''<section class="wrap editorial-grid"><article class="editorial-card"><span class="eyebrow">01 / DATA</span><h2>{t('Каталог через API','Catalogue API')}</h2><p>{t('Получайте характеристики и разрядные данные для интеграции в собственный сайт. Доступ выдаётся администратором.','Integrate specifications and discharge data into your website. Access is granted by an administrator.')}</p></article><article class="editorial-card"><span class="eyebrow">02 / CALCULATOR</span><h2>{t('Калькулятор в вашем стиле','A calculator in your style')}</h2><p>{t('Настройте цвета, заголовок, язык и режимы расчёта. Получите код для встраивания на согласованные сайты.','Choose colours, a heading, language and calculation modes. Get embed code for approved websites.')}</p></article><article class="editorial-card"><span class="eyebrow">03 / ACCOUNT</span><h2>{t('Персональный доступ','Individual access')}</h2><p>{t('Оставьте заявку. После рассмотрения администратор назначит права и передаст ссылку установки пароля.','Apply for access. After review, an administrator assigns permissions and provides a password setup link.')}</p></article></section><section class="wrap partner-cta"><h2>{t('Начнём сотрудничество?','Let’s work together.')}</h2>{link('/admin/','Подать заявку ↗','Apply for access ↗','button dark')}</section>''')
page('about','О YELLOW',intro('ABOUT / YELLOW','От характеристик<br>к решению.','From specifications<br>to a solution.','YELLOW — аккумуляторные батареи и инструменты для подбора резервного питания.','YELLOW batteries and tools for selecting standby power configurations.')+f'''<section class="wrap split section"><div><h2>{t('Единое пространство<br>для подбора.','One place<br>to make your selection.')}</h2></div><div class="large-copy"><p>{t('В каталоге собраны серии HR M, HRL M, HR WM и HRL WM. Для каждой модели доступны основные характеристики и отдельная техническая листовка.','The catalogue includes HR M, HRL M, HR WM and HRL WM series. Each model has principal specifications and a dedicated technical datasheet.')}</p><p>{t('Калькулятор помогает перейти от условий нагрузки к конфигурации батарей, а кабинет партнёра — использовать данные и расчёты на своём сайте.','The calculator helps turn load requirements into a battery configuration. The partner account brings these data and tools to your own website.')}</p></div></section>''')
page('contacts','Контакты',intro('CONTACT / YELLOW','Будем на связи.','Get in touch.','Вопросы доступа, документации и подключения партнёрских сервисов.','Questions about access, documents and partner integrations.')+f'''<section class="wrap contact-grid"><div class="contact-card"><p class="eyebrow">{t('АДМИНИСТРАТОР САЙТА','WEBSITE ADMINISTRATOR')}</p><a class="contact-mail" href="mailto:admin@yellow-battery.com">admin@yellow-battery.com ↗</a><p>{t('Доступ в кабинет и технические вопросы сайта.','Account access and website support.')}</p></div><div class="contact-card"><p class="eyebrow">{t('ПАРТНЁРАМ','PARTNERS')}</p><h2>{t('Заявка на подключение','Request access')}</h2>{link('/admin/','Открыть форму ↗','Open application form ↗','text-link')}</div><div class="company-card"><span>Harbin Haoneng New Energy Technology Co., Ltd.</span><span>yellow-battery.com</span></div></section>''')
page('404','Страница не найдена',intro('404','Такой страницы нет.','Page not found.','Перейдите в каталог или вернитесь на главную.','Explore the catalogue or return to the home page.')+f'<div class="wrap button-row">{link("/","На главную","Home","button dark")}{link("/catalog/","Каталог","Catalogue","button outline")}</div>')
copy_changed(OUT/'404/index.html',OUT/'404.html')
for file in (ROOT/'assets').iterdir():copy_changed(file,OUT/'assets'/file.name)
print('Built home, catalogue, 26 product pages, documents, applications, partners, about, contact.')
